float findMedian(int X[],int Y[],int m,int n)
{
    float median;
    int s = sizeof(int);

    int j=0; int k =0;
    int i=0;

    while(i<m+n)
    {
        if(j<m && k<n)
        {
            if(X[j]<=Y[k])
            {
                a[i] = X[j];
                j++;
            }
            else
            {
                a[i] = Y[k];
                k++;
            }
            i++;
        }

        else if(j == m)
        {
            a[i]=Y[k];
            k++;
            i++;
        }
        else if(k == n)
        {
            a[i]=X[j];
            j++;
            i++;
        }

    }

    if((m+n)%2 != 0)
    {
        median = a[(m+n)/2];
        return median;
    }
    else
    {
        median = (a[(m+n-1)/2]+a[(m+n-1)/2+1])/2.0;
        return median;
    }
}

