            if((ABA_temp[0] == BAB_temp[1]) && (ABA_temp[1] == BAB_temp[0])){
               if(!not_added){
                  ip_counter++;
                  not_added = true;
               }
            }
         }
      }
      in_brackets = false;
   }

   printf("answer=%d\n", ip_counter);
