int     ft_abs(int x)
{
    if (x < 0)
        return (x *  -1);
    return (x);
}
int     *ft_rrange(int start, int end)
{
    int     i;
    int     *tab;

    i = 0;
    if (!(tab = (int*)malloc(sizeof(int*) * (ft_abs(end - start) + 1))))
        return (NULL);
    if (end > start)
    {
        while (end >= start)
        tab[i++] = end--;
    }
    else if (end < start)
    {
        while (end <= start)
        tab[i++] = end++;
    }
    tab[i] = '\0';
    return (tab);
}
int     main ()
{
    int a;
    int *b;

    b = ft_rrange(0,-3);
    printf("%d %d %d %d %d %d",b[0],b[1],b[2],b[3],b[4],b[5]);

    return(0);
}
