void display(int array[MAX], int length)
{
    int i = 0;
    for(i=0; i<length; i++)
        printf("%d\t", array[i]);
}


void sorting(int array[MAX], int length)
{
    int i, j, temp = 0;
    int size = length;

    for(i=0; i<length; i++)
    {
        for(j=i+1; j<length; j++)
        {

            if(array[i] > array[j])
            {
                temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
    }


    display(array, size);
