int main()
{
    complex_t a, b, c;
    int escolha;

    do
    {
        do
        {
            printf("\nCalculadora de nÃºmeros complexs:\n");
            printf("\n\t(1) AdiÃ§Ã£o\n");
            printf("\t(2) SubtraÃ§Ã£o\n");
            printf("\t(3) MultiplicaÃ§Ã£o\n");
            printf("\t(4) DivisÃ£o\n");
            printf("\t(5) Sair\n");
            printf("\n\tDigite sua escolha: ");
