            case 2:
                le_complexs(&a, &b);
                c = subtracao(a,b);
                imprime_complex(&c);
                break;

            case 3:
                le_complexs(&a, &b);
                c = multiplicacao(a,b);
                imprime_complex(&c);
                break;

            case 4:
                le_complexs(&a, &b);
                c = divisao(a,b);
                imprime_complex(&c);
                break;

