int fatorial(int x){
  int i, fatorial=1;

  for(i=x;i>0;i--){
    fatorial = fatorial*i;
  }
  return fatorial;
}

int comb(int lin, int col){

 return fatorial(lin) / (fatorial(col) * fatorial(lin-col));
}
