#define MAXSIZE 100
struct Stack {
    int top;
    int array[MAXSIZE];
} string;

int isFull() {
    if(string.top >= MAXSIZE)
        return 1;
    else
        return 0;
}
int isEmpty() {
 if(string.top == -1)
     return 1;
 else
     return 0;
}
void push(int num) {
    if (isFull())
        printf("Stack is Full...\n");
    else {
        string.array[string.top + 1] = num;
        string.top++;
    }
}
int pop() {
    if (isEmpty())
        printf("Stack is Empty...\n");
    else {
     string.top = string.top - 1;
        return string.array[string.top+1];
    }
}

int main() {
    char inputString[100], c;
    int i, length;

    printf("Enter a string\n");
    gets(inputString);
    length = strlen(inputString);
    for(i = 0; i < length; i++){
        push(inputString[i]);
    }
    for(i = 0; i < length; i++){
        if(pop() != inputString[i]) {
            printf("Not a Palindrome String\n");
            return 0;
        }
    }

    printf("Palindrome String\n");
    return 0;
}
