typedef struct Node 
{
        int data; 
        struct Node *next; 
}node;

struct Node * insert(struct Node *head, int data, int index){
     struct Node * ptr = (struct Node *) malloc(sizeof(struct Node));
     struct Node * p = head;
     int i = 0;
     while (i!=index-1)
     {
          p = p->next;
          i++;
     }
     ptr->data = data;
     ptr->next = p->next;
     p->next = ptr;
     return head;

};

int find(node *ptr, int key)
{
        node *start = ptr;
        ptr =  ptr -> next; 

        while(ptr!=start)
        {
                if(ptr->data == key) 
                {
                        return 1;
                }
                ptr = ptr -> next;  
        }

        return 0;
}
struct Node * deleteByGivenKey(struct Node * head, int value){
     struct Node *p = head;
     struct Node *q = head->next;

     while ( q->data != value && q->next != NULL)
     {
          p = p->next;
          q = q->next;
     }

     if (q->data == value)
     {
          p->next = q->next;
          free(q);
     }

     return head;
}

void print(node *start,node *ptr)
{
        if(ptr==start)
        {
                return;
        }
        printf("%d ",ptr->data);
        print(start,ptr->next);
}
