{
    PLLCON = 1<<0;              
    PLLFEED = 0xAA;
    PLLFEED = 0x55;             
    PLLCFG = (1<<6)| 2; 
    PLLCFG &= ~(1<<5);
    while(!(PLLSTAT & (1<<10)));            
    PLLCON = (1<<1)|(1<<0);         
    PLLFEED = 0xAA;
    PLLFEED = 0x55;             
}

void pll_48MHz(void)
{
    PLLCON = 1<<0;              
    PLLFEED = 0xAA;
    PLLFEED = 0x55;             
    PLLCFG = (1<<5)| 3; 
    PLLCFG &= ~(1<<5);
    while(!(PLLSTAT & (1<<10)));            
    PLLCON = (1<<1)|(1<<0);         
    PLLFEED = 0xAA;
    PLLFEED = 0x55;             
}

void pll_12MHz(void)
{
    PLLCON = 1<<0;              
    PLLFEED = 0xAA;
    PLLFEED = 0x55;             
    PLLCFG = (1<<6)| (1<<5) | 0;    
    while(!(PLLSTAT & (1<<10)));            
    PLLCON = (1<<1)|(1<<0);         
    PLLFEED = 0xAA;
    PLLFEED = 0x55;             
}


