int HASH[10],key,val,i;
int H(int value)
{
    return(value%10);
}
void insert(int key,int value)
{
    int index=H(key);
    int i;
    if(HASH[index]==-1)
    {
        HASH[index]=value;
    }
    else
    {
        for(i=index+1;i<10;i++)
        {
            if(HASH[i]==-1)
            {
                HASH[i]=value;
                break;
            }
        }
    }
}
void delete(int key,int value)
{
    int index=H(key);
    int ct=0,i;
    if(HASH[index]==value)
    {
        HASH[index]=-1;
        printf("\nValue deleted");
        ct++;
    }
    else
    {
        for(i=index+1;i<10;i++)
        {
            if(HASH[i]==value)
            {
                HASH[i]=-1;
                printf("\nValue deleted");
                ct++;
                break;
            }
        }
    }
    if(ct==0)
    {
        printf("\nThe key with that value is not found");
    }
}
void search(int key,int value)
{
    int index=H(key);
    int i;
    int ct=0;
    if(HASH[index]==value)
    {
        printf("\nThe value found at index %d ",index);
        ct++;
    }
    else
    {
        for(i=index+1;i<10;i++)
        {
            if(HASH[i]==value)
            {
                printf("\nValue found at index %d ",i);
                ct++;
                break;
            }
        }
    }
    if(ct==0)
    {
        printf("\nThe key with that value is not found");
    }   
}
