                    currentIsland = TravelToPrevIsland(parentIsland, currentIsland, stackHead);
                }
                else
                {
                    currentIsland = TravelToStartIsland(start, currentIsland, stackHead);
                    *flagForGameOver = 1;
                }
            }
            else
