typedef struct 
{
    int arr[MAX];
    int front,rear;
}QUEUE;
void init(QUEUE* q)
{
    q->front=-1;
    q->rear=-1;
}
void add(int e,QUEUE* q)
{
    if(q->rear==MAX-1)
    {
        printf("QUEUE FULL\n");
        return;
    }
    q->rear+=1;
    q->arr[q->rear]=e;
}
int del(QUEUE* q)
{
    if(q->front==q->rear)
    {
        printf("QUEUE EMPTY\n");
        return -1;
    }
    q->front+=1;
    return q->arr[q->front];
}
Ans find(QUEUE* q,int e)
{
    QUEUE q1;
    QUEUE* nq=&q1;
    int num;
    Ans f=False;
    init(nq);
    while(q->front!=q->rear)
    {
        num=del(q);
        if(num==e)
        {
            f=True;
            add(num,nq);
        }
        else
            add(num,nq);
    }
    while(nq->front!=nq->rear)
    {
        add(del(nq),q);
    }
    return f;
}
