} cNum;

cNum add(cNum a, cNum b)
{
    cNum temp;

    temp.real = a.real + b.real;
    temp.imag = a.imag + b.imag;

    return temp;
}

cNum subtract(cNum a, cNum b)
{
    cNum temp;

    temp.real = a.real - b.real;
    temp.imag = a.imag - b.imag;

    return temp;
}

cNum multiply(cNum a, cNum b)
{
    cNum temp;

    temp.real = a.real * b.real - a.imag * b.imag;
    temp.imag = a.imag * b.real + a.real * b.imag;

    return temp;
}

void display(cNum a)
{
