        printf("Command: "); scanf("%d", &ch);

        switch(ch)
        {
            case 1:

                    scanf("%d", &ele);
                    insertRear(head, ele);
                    break;

            case 2:
                    display(head);
                    break;

            case 3: 
                    removeDuplicate2(head);
        }

    }while(ch != 0);
