   {

      res = os_sem_wait(semaphore, 0xFFFF);
   }
   else
   {

      timeout = OS_MS_TO_SYSTICKS(timeout);


      do
      {

         n = MIN(timeout, 0xFFFE);

         res = os_sem_wait(semaphore, n);

         timeout -= n;


      } while(res == OS_R_TMO && timeout > 0);
