   error_t error;
   MacAddr bridgeAddr;


   if(*valueLen < sizeof(MacAddr))
      return ERROR_BUFFER_OVERFLOW;


   bridgeAddr = MAC_UNSPECIFIED_ADDR;

#if (STP_SUPPORT == ENABLED)

   if(bridgeMibBase.stpBridgeContext != NULL)
